import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

from collections import deque
def solve(inp,bg):
    h,w=len(inp),len(inp[0])
    seen=set()
    dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if inp[i][j]==bg and (i,j) not in seen: seen.add((i,j));dq.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if inp[i][j]==bg and (i,j) not in seen: seen.add((i,j));dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and inp[ni][nj]==bg and (ni,nj) not in seen:
                seen.add((ni,nj));dq.append((ni,nj))
    out=[row[:] for row in inp]
    for i in range(h):
        for j in range(w):
            if inp[i][j]==bg and (i,j) not in seen:
                out[i][j]=4
    return out
din=G['Demo pair 1 input']; dout=G['Demo pair 1 output']
print(solve(din,5)==dout)
tout=solve(G['Test input'],6)
for r in tout: print(' '.join(map(str,r)))
